input.command:
for app in angular2-hn angular-contacts angular-fuxa angular-kubernetes-dashboard react-dashboard; do
node -e "
const fs=require('fs');
const p='./evidence/runs/$app/run-record.json';
if(!fs.existsSync(p)){console.log('$app','NO run-record.json', fs.readdirSync('./evidence/runs/$app').join(','));process.exit(0)}
const r=require(p);
const ran=r.stages.filter(s=>s.status==='ran').length;
const bad=r.stages.find(s=>s.status!=='ran');
console.log('$app'.padEnd(30),'| outcome',r.outcome,'| ',ran+'/9','| stopped at',bad?bad.name+':'+bad.status:'-','|',(bad&&bad.reason?bad.reason.split('\n')[0]:'').slice(0,150));
const iv='./evidence/runs/$app/run-record.json.interventions.json';
if(fs.existsSync(iv)){const i=require(iv); console.log('   intervention:',i.terminalClassification,'count',i.interventionCount,'| argv',i.attempts[0].argv.filter(a=>a.startsWith('--')).join(' '),'|',i.attempts[0].startedAt);}
"
done

